#!/usr/bin/env node
/**
 * Regenerate `src/vendor/pi-ai` from the installed, lockfile-resolved pi-ai release.
 * See ARCHITECTURE.md → `src/vendor/pi-ai` for the host-loader constraint and
 * dependency upgrade workflow.
 *
 * Usage:
 *   node scripts/vendor-pi-ai.mjs           # regenerate
 *   node scripts/vendor-pi-ai.mjs --check   # fail if the committed copy is stale
 */
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const vendorDir = join(repoRoot, "src", "vendor", "pi-ai");
const piAiDist = join(repoRoot, "node_modules", "@earendil-works", "pi-ai", "dist");
const piAiPackageJson = join(repoRoot, "node_modules", "@earendil-works", "pi-ai", "package.json");

/** pi-ai modules copied into the extension, and the file each becomes. */
const SOURCES = [
	{ from: "api/constrained-sampling.js", to: "constrained-sampling.ts" },
	{ from: "api/openai-responses-shared.js", to: "openai-responses-shared.ts" },
	{ from: "api/transform-messages.js", to: "transform-messages.ts" },
	{ from: "utils/hash.js", to: "hash.ts" },
	{ from: "utils/sanitize-unicode.js", to: "sanitize-unicode.ts" },
];

/**
 * Import rewrites. pi-ai's own modules that Pi does not expose to extensions are
 * copied; everything Pi does expose (or that only needs a helper) is imported from
 * the host through `host.ts`.
 */
const IMPORT_REWRITES = new Map([
	['from "../models.js"', 'from "./host.ts"'],
	['from "../utils/json-parse.js"', 'from "./host.ts"'],
	['from "../utils/text.js"', 'from "./host.ts"'],
	['from "../utils/transcript.js"', 'from "./host.ts"'],
	['from "../utils/hash.js"', 'from "./hash.ts"'],
	['from "../utils/sanitize-unicode.js"', 'from "./sanitize-unicode.ts"'],
	['from "./constrained-sampling.js"', 'from "./constrained-sampling.ts"'],
	['from "./transform-messages.js"', 'from "./transform-messages.ts"'],
]);

function fail(message) {
	console.error(`vendor-pi-ai: ${message}`);
	process.exit(1);
}

if (!existsSync(piAiDist)) {
	fail(
		`@earendil-works/pi-ai is not installed at ${piAiDist}. Run \`npm install\` before vendoring.`,
	);
}

const piAiVersion = JSON.parse(readFileSync(piAiPackageJson, "utf-8")).version;

function render(sourcePath, source) {
	const sha256 = createHash("sha256").update(source).digest("hex");
	let body = source;
	for (const [from, to] of IMPORT_REWRITES) {
		body = body.split(from).join(to);
	}
	body = body.replace(/^\/\/# sourceMappingURL=.*$/gm, "");
	const header = [
		"// @ts-nocheck",
		`// Vendored from @earendil-works/pi-ai ${piAiVersion} (MIT): ${sourcePath}`,
		"// Generated by scripts/vendor-pi-ai.mjs - do not edit by hand.",
		`// Source sha256: ${sha256}`,
		"",
	].join("\n");
	return `${header}${body.trimEnd()}\n`;
}

const generated = new Map();
for (const { from, to } of SOURCES) {
	const sourcePath = join(piAiDist, from);
	if (!existsSync(sourcePath)) {
		fail(`missing pi-ai module ${from} (pi-ai ${piAiVersion})`);
	}
	generated.set(to, render(from, readFileSync(sourcePath, "utf-8")));
}

const check = process.argv.includes("--check");
let stale = false;
for (const [name, content] of generated) {
	const target = join(vendorDir, name);
	if (check) {
		const current = existsSync(target) ? readFileSync(target, "utf-8") : "";
		if (current !== content) {
			console.error(`vendor-pi-ai: ${name} is stale - run \`npm run vendor:pi-ai\``);
			stale = true;
		}
		continue;
	}
	mkdirSync(dirname(target), { recursive: true });
	writeFileSync(target, content);
	console.log(`vendor-pi-ai: wrote src/vendor/pi-ai/${name}`);
}

if (stale) {
	process.exit(1);
}
if (check) {
	console.log(`vendor-pi-ai: src/vendor/pi-ai matches @earendil-works/pi-ai ${piAiVersion}`);
}
